    for f in formulas_str:
        try:
            expr = eval(f, {"__builtins__": {}}, ns)
            if z3.is_expr(expr):
                parsed.append(expr)
            elif isinstance(expr, bool):
                parsed.append(z3.BoolVal(expr))
        except Exception:
            pass
    return parsed


